    }

    [TestMethod]
    public async Task ChargeAsync_EmptyToken_Throws()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync("", 10m));
    }

    [TestMethod]
    public async Task ChargeAsync_WhitespaceToken_Throws()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync("   ", 10m));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    [DataRow(-100.50)]
    public async Task ChargeAsync_NonPositiveAmount_Throws(double amount)
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_valid", (decimal)amount));
        Assert.AreEqual("amount", ex.ParamName);
    }

    // ──────────────────────────────────────────────
    //  ChargeAsync — success path
    // ──────────────────────────────────────────────

    [TestMethod]
    public async Task ChargeAsync_ValidInput_ReturnsSuccessResult()
    {
        var expected = new ChargeResult("ch_123", true);
        _provider.ChargeResultToReturn = expected;

        var result = await _gateway.ChargeAsync("tok_abc", 49.99m);

        Assert.AreEqual(expected.ChargeId, result.ChargeId);
        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_ValidInput_ForwardsTokenAndAmount()
    {
        await _gateway.ChargeAsync("tok_forwarded", 25.00m);

        Assert.AreEqual("tok_forwarded", _provider.LastCardToken);
        Assert.AreEqual(25.00m, _provider.LastAmount);
    }

    // ──────────────────────────────────────────────
    //  ChargeAsync — failure / provider error
    // ──────────────────────────────────────────────

    [TestMethod]
    public async Task ChargeAsync_ProviderReturnsFailure_PropagatesResult()
    {
