        var result = await _gateway.ChargeAsync("tok_abc", 10m);

        Assert.IsFalse(result.Success);
        Assert.AreEqual("ch_fail", result.ChargeId);
    }

    [TestMethod]
    public async Task ChargeAsync_ProviderThrows_ExceptionPropagates()
    {
        _provider.ExceptionToThrow = new InvalidOperationException("provider down");

        await Assert.ThrowsExactlyAsync<InvalidOperationException>(
            async () => await _gateway.ChargeAsync("tok_abc", 10m));
    }

    // ──────────────────────────────────────────────
    //  RefundAsync — validation
    // ──────────────────────────────────────────────

    [TestMethod]
    public async Task RefundAsync_NullChargeId_Throws()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(null!));
    }

    [TestMethod]
    public async Task RefundAsync_EmptyChargeId_Throws()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(""));
    }

    // ──────────────────────────────────────────────
    //  RefundAsync — success path
    // ──────────────────────────────────────────────

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccessResult()
    {
        var expected = new RefundResult("rf_456", true);
        _provider.RefundResultToReturn = expected;

        var result = await _gateway.RefundAsync("ch_123");

        Assert.AreEqual(expected.RefundId, result.RefundId);
        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ForwardsChargeId()
    {
        await _gateway.RefundAsync("ch_forwarded");

        Assert.AreEqual("ch_forwarded", _provider.LastChargeId);
    }

    [TestMethod]
    public async Task RefundAsync_ProviderThrows_ExceptionPropagates()
    {
        _provider.ExceptionToThrow = new InvalidOperationException("refund error");

        await Assert.ThrowsExactlyAsync<InvalidOperationException>(
            async () => await _gateway.RefundAsync("ch_123"));
    }

    // ──────────────────────────────────────────────
    //  ProcessWebhook — validation
    // ──────────────────────────────────────────────

    [TestMethod]
    public void ProcessWebhook_NullEventType_Throws()
    {
        Assert.ThrowsExactly<ArgumentException>(
            () => _gateway.ProcessWebhook(null!, "{}"));
    }

    [TestMethod]
    public void ProcessWebhook_NullPayload_Throws()
    {
        Assert.ThrowsExactly<ArgumentException>(
            () => _gateway.ProcessWebhook("charge.succeeded", null!));
    }

    // ──────────────────────────────────────────────
    //  ProcessWebhook — known events (data-driven)
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow("charge.succeeded", true,  "Charge confirmed")]
    [DataRow("charge.failed",    false, "Charge declined")]
    [DataRow("refund.completed",  true,  "Refund processed")]
    public void ProcessWebhook_KnownEvent_ReturnsExpected(
        string eventType, bool expectedHandled, string expectedMessage)
    {
        var result = _gateway.ProcessWebhook(eventType, "{\"id\":\"evt_1\"}");

        Assert.AreEqual(expectedHandled, result.Handled);
        Assert.AreEqual(expectedMessage, result.Message);
    }

    // ──────────────────────────────────────────────
    //  ProcessWebhook — unknown event
    // ──────────────────────────────────────────────

    [TestMethod]
    public void ProcessWebhook_UnknownEvent_ReturnsNotHandled()
    {
        var result = _gateway.ProcessWebhook("invoice.created", "{}");

        Assert.IsFalse(result.Handled);
        Assert.Contains("Unknown event", result.Message);
    }
}

